package com.shici.app.core.q1

import org.junit.Assert.*
import org.junit.Test
import java.io.File

/** Source wiring proofs only, deliberately separate from JVM behavior and real Android execution. */
class Q1SourceChainAcceptanceTest {
 private val root=File(requireNotNull(System.getProperty("q1.source")))
 private val capture=File(root,"app/src/main/java/com/shici/app/capture/CaptureService.kt").readText()
 private val view=File(root,"app/src/main/java/com/shici/app/capture/LiveSelectionView.kt").readText()
 private fun between(a:String,b:String)=capture.substringAfter(a).substringBefore(b)
 @Test fun bubbleClickWiresToNewLiveEntry(){assertTrue(capture.contains("view.setOnClickListener { beginLiveSelection() }"));assertFalse(Regex("\\bSelectionView\\(").containsMatchIn(capture))}
 @Test fun noScreenshotRenderingOrFinishInLiveView(){assertFalse(view.contains("drawBitmap"));assertFalse(view.contains("Bitmap"+"("));assertFalse(view.contains("完成划选"));assertTrue(view.contains("MotionEvent.ACTION_UP"));assertTrue(view.contains("onStroke(HighlighterStroke(points.map(::toScreen)))"))}
 @Test fun entryHidesBubbleBeforeArmingFrame(){val code=between("private fun beginLiveSelection()","private fun onEntryFrame");val remove=code.indexOf("removeBubble()");val arm=code.indexOf("armFrame(FramePurpose.ENTRY, body, SystemClock.elapsedRealtime() + ENTRY_FRAME_TIMEOUT_MS)");assertTrue("entry removal exists",remove>=0);assertTrue("new atomic publisher exists",arm>=0);assertTrue("entry removal precedes publication",remove<arm);assertTrue(code.contains("deletionCredential = app.repository.deletions.capture()"))}
 @Test fun liftRemovesFullLayerBeforeVerificationFrame(){val code=between("private fun commitLiveStroke(","private fun onVerifyFrame(");val remove=code.indexOf("removeLiveLayer()");val arm=code.indexOf("armFrame(FramePurpose.VERIFY, session.body,");assertTrue("lift layer removal exists",remove>=0);assertTrue("new atomic publisher exists",arm>=0);assertTrue("lift layer removal precedes publication",remove<arm);assertTrue(code.contains("SystemClock.elapsedRealtime() + VERIFY_FRAME_TIMEOUT_MS"));assertTrue(code.contains("perf.selectionSubmit()"))}
 @Test fun requestUsesObservedFrameNotFixedSleep(){val code=between("private fun armFrame(","private fun beginLiveSelection()");assertTrue(code.contains("Choreographer.getInstance().postFrameCallback"));assertTrue(code.contains("request.arm(System.nanoTime())"));assertFalse(capture.contains("Thread.sleep"))}
 @Test fun readerGuardsSourceDimensionsTokenAndFreshness(){val code=between("private fun newReader(","private fun imageBitmap(");listOf("source === reader","image.width == source.width","image.height == source.height","frameIsCurrent(request)","request.canInspect(image.timestamp","request.complete(SystemClock.elapsedRealtime())","requestedFrame.compareAndSet(request, null)","image.close()").forEach{assertTrue(it,code.contains(it))}}
 @Test fun cleanLiftIsOnlyFramePassedToRecognizer(){val code=between("private fun onVerifyFrame(","private fun failLiveLookup(");assertTrue(code.contains("!session.entryFingerprint.matches(fingerprint)"));assertTrue(code.contains("recognize(bitmap, selection, session.deletionCredential)"));assertFalse(between("private fun onEntryFrame(","private fun commitLiveStroke(").contains("recognize("))}
 @Test fun configurationAndProjectionResizeInvalidateThroughDismiss(){val resize=between("private fun resize(","override fun onConfigurationChanged(");assertTrue(resize.contains("dismissPanel()"));assertTrue(capture.contains("override fun onCapturedContentResize(width: Int, height: Int)"));assertTrue(capture.contains("if (width != screenWidth || height != screenHeight) resize(width, height)"))}
 @Test fun systemStopChangesGenerationAndDestroyInvalidates(){assertTrue(capture.contains("override fun onStop() { if (!stopped) CaptureStatus.stop(this@CaptureService) }"));val status=File(root,"app/src/main/java/com/shici/app/capture/CaptureStatus.kt").readText();assertTrue(status.substringAfter("fun stop(context:").contains("generation += 1"));val destroy=capture.substringAfter("override fun onDestroy()");listOf("stopped = true","dismissPanel(); removeBubble()","display?.release()","projection?.stop()","reader?.setOnImageAvailableListener(null, null)","old?.close()","framesThread.quitSafely()","recognizer?.close()").forEach{assertTrue(it,destroy.contains(it))}}
 @Test fun liveWindowIsTransparentAndOnlyModeFullScreen(){val code=between("private fun addLiveLayer(","private fun removeLiveLayer(");assertTrue(code.contains("MATCH_PARENT"));assertTrue(code.contains("PixelFormat.TRANSLUCENT"));assertFalse(code.contains("DIM_BEHIND"));val panel=between("private fun addPanel(","private fun removePanelView(");assertTrue(panel.contains("FLAG_NOT_TOUCH_MODAL"));assertFalse(panel.contains("MATCH_PARENT"))}
 @Test fun repositoryAdmissionRemainsGuardedAndCredentialNotRecaptured(){val code=between("private fun showDefinition(","private fun card(");assertTrue(code.contains("app.repository.record(event, entry, replaces, credential) { sessionIsActive() && gate.accepts(token) }"));assertTrue(code.contains("definitionCardStale(guard)"));assertFalse(code.contains("deletions.capture()"))}
 @Test fun noNewPermissionsOrSchemaChangesInAllowedCandidate(){val old=File(root,"app/src/main/AndroidManifest.xml").readText();assertFalse(old.contains("BIND_ACCESSIBILITY_SERVICE"));val granted=javax.xml.parsers.DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(old.byteInputStream()).getElementsByTagName("uses-permission");assertFalse((0 until granted.length).map{granted.item(it) as org.w3c.dom.Element}.any{it.getAttribute("android:name")=="android.permission.INTERNET"&&it.getAttribute("tools:node")!="remove"});assertFalse(capture.contains("compress("));assertFalse(capture.contains("FileOutputStream"))}
}
